import express from 'express';
import dotenv from 'dotenv';
import { InMemoryUserRepository } from './infrastructure/repositories/in-memory-user.repository.js';
import { CreateUserUseCase } from './application/use-cases/create-user.use-case.js';
import { UserController } from './interfaces/http/controllers/user.controller.js';
import { createUserRoutes } from './interfaces/http/routes/user.routes.js';

dotenv.config();
const app = express();
app.use(express.json());

// Composition Root (Dependency Injection)
const userRepo = new InMemoryUserRepository();
const createUserUseCase = new CreateUserUseCase(userRepo);
const userController = new UserController(createUserUseCase);

app.use('/api/v1', createUserRoutes(userController));

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`🚀 Server ready on http://localhost:${port}`);
});

