from fastapi import APIRouter, Depends
from app.application.dtos.item_dto import CreateItemDTO, ItemResponseDTO
from app.application.services.item_service import ItemService
from app.infrastructure.repositories.in_memory_item_repo import InMemoryItemRepository

router = APIRouter(prefix="/items", tags=["items"])
_repo = InMemoryItemRepository()

def get_item_service() -> ItemService:
    return ItemService(_repo)

@router.post("", response_model=ItemResponseDTO, status_code=201)
async def create_item(dto: CreateItemDTO, service: ItemService = Depends(get_item_service)):
    item = await service.create_item(dto)
    return ItemResponseDTO(id=item.id, title=item.title, price=item.price)

